import itertools

def count_valid_numbers(L):
    """
    Counts the number of natural numbers of length L using digits {0, 1, 2, 8}
    that are divisible by 3.
    """
    valid_count = 0
    allowed_digits = [0, 1, 2, 8]

    # Determine possible starting digits (must be non-zero for L >= 1)
    start_digits = [d for d in allowed_digits if d != 0]

    if L == 1:
        # L=1: The number itself must be divisible by 3.
        for d1 in start_digits:
            if d1 % 3 == 0:
                valid_count += 1
        return valid_count

    # For L > 1, we use itertools.product
    # First digit must be in start_digits
    # Remaining L-1 digits can be in allowed_digits

    for d1 in start_digits:
        # Iterate over all combinations for the remaining L-1 positions
        for combo in itertools.product(allowed_digits, repeat=L - 1):
            digits = [d1] + list(combo)

            # Check divisibility by 3 (sum of digits)
            if sum(digits) % 3 == 0:
                valid_count += 1

    return valid_count

# Calculate counts for L = 1, 2, 3, 4
L_values = [1, 2, 3, 4]
results = {}
for L in L_values:
    results[L] = count_valid_numbers(L)

print("--- Results ---")
for L, count in results.items():
    print(f"L={L}: Count = {count}")
